        for (;;) { int nx = -1; for (int e = t->adj_start[c]; e < t->adj_start[c + 1]; e++) { int w = t->adj[e]; if (!removed[w] && w != p[c] && sz[w] * 2 > tl) nx = w; } if (nx < 0) break; c = nx; }
